import StatisticsCards from '@/components/cards/StatisticsCards';
import PeopleIcon from '@/components/icons/PeopleIcon';
import TwoUserIcon from '@/components/icons/TwoUsersIcon';
import UserMinusIcon from '@/components/icons/UserMinusIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { Card } from '@/types/statistics';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';

export default function SalariesDetailsStatistics() {
    const [loading, setLoading] = useState(true);
    const [totalEmployees, setTotalEmployees] = useState(0);
    const [totalPaid, setTotalPaid] = useState(0);
    const [avgSalary, setAvgSalary] = useState(0);
    const [totalAllowances, setTotalAllowances] = useState(0);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            setLoading(true);
            try {
                const now = new Date();
                const month = now.getMonth() + 1;
                const year = now.getFullYear();

                const first = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: { page: 1, pageSize: 1, month, year },
                });
                const total: number = first.data.data.pagination?.total ?? 0;
                if (total === 0) {
                    if (!cancelled) {
                        setTotalEmployees(0);
                        setTotalPaid(0);
                        setAvgSalary(0);
                        setTotalAllowances(0);
                    }
                    return;
                }

                const res = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: { page: 1, pageSize: Math.min(total, 5000), month, year },
                });
                const rows = res.data.data.data as {
                    total_salary?: number;
                    total_allowances?: number;
                }[];

                const sumPaid = rows.reduce((acc, r) => acc + (Number(r.total_salary) || 0), 0);
                const sumAllowances = rows.reduce((acc, r) => acc + (Number(r.total_allowances) || 0), 0);
                const avg = total > 0 ? Math.round(sumPaid / total) : 0;

                if (!cancelled) {
                    setTotalEmployees(total);
                    setTotalPaid(Math.round(sumPaid));
                    setAvgSalary(avg);
                    setTotalAllowances(Math.round(sumAllowances));
                }
            } catch {
                if (!cancelled) {
                    setTotalEmployees(0);
                    setTotalPaid(0);
                    setAvgSalary(0);
                    setTotalAllowances(0);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = useMemo(
        () => [
            { text: 'إجمالي الرواتب', num: totalPaid.toLocaleString('en-US'), icon: <PeopleIcon />, label: 'ريال', percent: 0 },
            { text: 'عدد الموظفين', num: totalEmployees, icon: <TwoUserIcon />, percent: 0 },
            { text: 'متوسط الراتب', num: avgSalary.toLocaleString('en-US'), icon: <UserMinusIcon />, label: 'ريال', percent: 0 },
            { text: 'إجمالي البدلات', num: totalAllowances.toLocaleString('en-US'), icon: <UserRemoveIcon />, label: 'ريال', percent: 0 },
        ],
        [totalPaid, totalEmployees, avgSalary, totalAllowances],
    );

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
